mapper.select:
select qs.*, qas.id qas_id, qas.answer, qas.keywords, qas.create_time qas_create_time, qas.update_time qas_update_time from questions qs left join question_answers qas on qs.id = qas.question_id where qs.is_deleted = 0 and qas.is_deleted = 0
and qs.type = #{questionQueryVo.type}
and qs.difficulty = #{questionQueryVo.difficulty}
and qs.category_id = #{questionQueryVo.categoryId}
and title like concat('%',#{questionQueryVo.keyword},'%')
order by qs.create_time desc
